def year_of(date: str) -> str:
    match = re.search(r"(?:19|20)\d{2}", date or "")
    return match.group(0) if match else "n.d."


def authors_of(creators: list[dict]) -> list[str]:
    result = []
    for creator in creators:
        name = creator.get("name") or " ".join(
            part for part in (creator.get("firstName", ""), creator.get("lastName", "")) if part
        )
        if name:
            result.append(name)
    return result


def q(value) -> str:
    return json.dumps(value, ensure_ascii=False)


def main() -> None:
    snapshot = {item["key"]: item["data"] for item in json.loads(SNAPSHOT.read_text())}
    PAPERS.mkdir(exist_ok=True)
    catalog = []
    for order, row in enumerate(A, start=1):
        (key, category, tier, evidence, context, sample, reason, finding,
         limitations, implication, scores, basis, topics) = row
        data = snapshot[key]
        authors = authors_of(data.get("creators", []))
        year = year_of(data.get("date", ""))
        doi = (data.get("DOI") or "").strip()
        record = {
            "order": order, "zotero_key": key, "title": data["title"],
            "authors": authors, "year": year,
            "journal": data.get("publicationTitle") or "Journal title requires verification",
            "doi": doi, "category": category, "tier": tier,
            "evidence_type": evidence, "context": context, "sample": sample,
            "inclusion_reason": reason, "main_finding": finding,
            "limitations": limitations, "nexus_implication": implication,
            "score_relevance": scores[0], "score_rigor": scores[1],
            "score_contribution": scores[2], "score_transferability": scores[3],
            "score_equity": scores[4], "score_total": sum(scores),
            "review_basis": basis, "reviewed_date": REVIEWED, "topics": topics,
        }
        catalog.append(record)
        front = ["---", "layout: paper"]
        for field in ("order","zotero_key","title","authors","year","journal","doi","category","tier",
                      "evidence_type","context","sample","inclusion_reason","score_relevance","score_rigor",
                      "score_contribution","score_transferability","score_equity","score_total","review_basis",
                      "reviewed_date","topics"):
            front.append(f"{field}: {q(record[field])}")
        front.append("---")
        body = f"""
## Why this paper is included

{reason}

## Evidence and main finding

**Design:** {evidence}. **Context:** {context}. **Sample:** {sample}.

{finding}

## Important limitations

{limitations}

## Implication for NEXUS

{implication}

## Appraisal note

This is a {basis.lower()} completed on {REVIEWED}. The score is an editorial aid under the [published NEXUS rubric]({{{{ '/methodology/' | relative_url }}}}); it is not a precise ranking or a substitute for independent scholarly review.
"""
        (PAPERS / f"{order:02d}-{key.lower()}.md").write_text("\n".join(front) + body, encoding="utf-8")
    CATALOG.write_text(json.dumps(catalog, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"generated {len(catalog)} paper appraisals")


if __name__ == "__main__":
    main()
